import javax.swing.*;import java.awt.*;import java.awt.event.*;import java.awt.event.ActionEvent;public class AccountWindow extends JDialog{	private Bank bank;	private Account account;	private Frame framer;	private JPanel name_panel = new JPanel();	private JButton your_button = new JButton("Ok");	private JTextField name_field, lname_field, account_field, phone_field;	private JTextField balance;	private JLabel name_label, lname_label, phone_label, account_label;	private JLabel balance_label;	private String default_error_message = new String("Error: ");	public AccountWindow(Frame parent, boolean modal, Bank this_bank, Account this_account){			super(parent, modal);		framer = parent;		bank = this_bank;		account = this_account;		setResizable(false);		setTitle("Northfield Bank:");		name_field = new JTextField("", 15); 		lname_field = new JTextField("", 15); 		account_field = new JTextField("", 15); 		phone_field = new JTextField("", 15);		balance = new JTextField("", 15);		name_label = new JLabel("First Name: "); 		lname_label = new JLabel("Last Name: "); 		account_label = new JLabel("Account Number: "); 		phone_label = new JLabel("Phone Number: ");		balance_label = new JLabel("Balance: ");				name_panel.setLayout(new GridLayout(5,2));		name_panel.add(name_label);		name_panel.add(name_field);		name_panel.add(lname_label);		name_panel.add(lname_field);		name_panel.add(phone_label);		name_panel.add(phone_field);		name_panel.add(account_label);		name_panel.add(account_field);		name_panel.add(balance_label);		name_panel.add(balance);		getContentPane().setLayout(new BorderLayout(10,10));		getContentPane().add(name_panel, BorderLayout.CENTER);	}	private void addButtons(){};	private void clearFields(){			name_field.setText(""); 		lname_field.setText("");		account_field.setText("");		phone_field.setText("");		balance.setText("");		}}